//! `storage.signedUrlKeys`: with a key registered, the strict profile verifies the V4 signature of
//! a signed URL against its canonical request, as Cloud Storage does, and answers 403
//! `SignatureDoesNotMatch` for an altered signature, a changed signed header value or another
//! object (the four causes recorded in production). Without a key nothing is verified. The keys in
//! this file are generated by the tests and are never real credentials.

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex, OnceLock};

use fireemu_adapter_http::storage::{
    handle, StorageRequest, StorageResponse, StorageRulesRegistry, StorageState,
};
use fireemu_adapter_http::storage_signature::SignerKeys;
use fireemu_core_auth::jwt::TokenAcceptance;
use fireemu_core_auth::mfa::TotpPolicy;
use fireemu_core_auth::store::AuthStore;
use fireemu_core_rules::runtime::{LoadedRules, RulesetSlot};
use fireemu_core_session::clock::VirtualClock;
use fireemu_core_storage::name::{BucketName, ObjectName};
use fireemu_core_storage::store::StorageState as ObjectStore;
use fireemu_core_storage::store::{NewMetadata, Precondition};
use fireemu_core_types::determinism::SplitMix64;
use fireemu_core_types::time::LogicalInstant;
use rsa::pkcs1v15::SigningKey;
use rsa::pkcs8::{EncodePrivateKey as _, EncodePublicKey as _, LineEnding};
use rsa::signature::{SignatureEncoding as _, Signer as _};
use rsa::RsaPrivateKey;
use sha2::{Digest as _, Sha256};

const START: LogicalInstant = LogicalInstant::from_unix_seconds(1_788_004_860);
const BUCKET: &str = "demo-app.appspot.com";
const HOST: &str = "127.0.0.1:9199";
const EMAIL: &str = "signer@demo-app.iam.gserviceaccount.com";
const ALLOW_ALL_RULES: &str = "rules_version = '2'; service firebase.storage { match /b/{bucket}/o { match /{path=**} { allow read, write: if true; } } }";

fn key() -> &'static RsaPrivateKey {
    static KEY: OnceLock<RsaPrivateKey> = OnceLock::new();
    KEY.get_or_init(|| {
        use rand_core::SeedableRng as _;
        RsaPrivateKey::new(&mut rand_chacha::ChaCha8Rng::seed_from_u64(7), 2048).unwrap()
    })
}

fn other_key() -> &'static RsaPrivateKey {
    static KEY: OnceLock<RsaPrivateKey> = OnceLock::new();
    KEY.get_or_init(|| {
        use rand_core::SeedableRng as _;
        RsaPrivateKey::new(&mut rand_chacha::ChaCha8Rng::seed_from_u64(8), 2048).unwrap()
    })
}

fn state(acceptance: TokenAcceptance, keys: Option<&[&str]>) -> StorageState {
    let s = StorageState {
        store: Mutex::new(ObjectStore::new(9)),
        clock: Arc::new(Mutex::new(VirtualClock::new(START))),
        auth: Arc::new(fireemu_core_auth::store::AuthRegistry::new(
            "demo-app",
            Arc::new(Mutex::new(AuthStore::new(
                "demo-app",
                SplitMix64::new(3),
                TotpPolicy::default(),
            ))),
        )),
        tenancy: None,
        rules: Arc::new(StorageRulesRegistry::global(Arc::new(RulesetSlot::new(
            LoadedRules::from_source(ALLOW_ALL_RULES).unwrap(),
        )))),
        project: "demo-app".to_owned(),
        events: None,
        barrier: None,
        firestore: None,
        faults: None,
        clock_observer: None,
        app_check_policy: None,
        admin_capability: None,
        server_requests: fireemu_adapter_http::storage::StorageServerRequests::default(),
        token_acceptance: acceptance,
        allow_unsigned_id_tokens: acceptance == TokenAcceptance::EmulatorMock,
        control_token: Some("storage-test-control-token".to_owned()),
    };
    if let Some(files) = keys {
        let mut registered = SignerKeys::default();
        for file in files {
            registered.add_file_contents(file.as_bytes()).unwrap();
        }
        s.rules.set_signer_keys(registered);
    }
    s
}

fn public_pem() -> String {
    key()
        .to_public_key()
        .to_public_key_pem(LineEnding::LF)
        .unwrap()
}

fn strict_with_key() -> StorageState {
    state(TokenAcceptance::Verified, Some(&[&public_pem()]))
}

fn encode(text: &str) -> String {
    use std::fmt::Write as _;
    let mut out = String::new();
    for byte in text.bytes() {
        if byte.is_ascii_alphanumeric() || b"-_.~".contains(&byte) {
            out.push(char::from(byte));
        } else {
            write!(out, "%{byte:02X}").unwrap();
        }
    }
    out
}

/// One signed URL as `@google-cloud/storage` builds it: the canonical request is assembled from
/// the documented layout, written out here rather than shared with the server.
struct Url {
    path: String,
    query: String,
}

fn hex(bytes: &[u8]) -> String {
    use std::fmt::Write as _;
    bytes.iter().fold(String::new(), |mut out, b| {
        write!(out, "{b:02x}").unwrap();
        out
    })
}

fn sign(
    private_key: &RsaPrivateKey,
    email: &str,
    method: &str,
    object: &str,
    date: &str,
    expires: &str,
    signed_headers: &[(&str, &str)],
) -> Url {
    use std::fmt::Write as _;
    let path = format!(
        "/{BUCKET}/{}",
        object.split('/').map(encode).collect::<Vec<_>>().join("/")
    );
    let names = signed_headers
        .iter()
        .map(|(n, _)| *n)
        .collect::<Vec<_>>()
        .join(";");
    let scope = format!("{}/auto/storage/goog4_request", &date[..8]);
    let params = BTreeMap::from([
        ("X-Goog-Algorithm", "GOOG4-RSA-SHA256".to_owned()),
        ("X-Goog-Credential", format!("{email}/{scope}")),
        ("X-Goog-Date", date.to_owned()),
        ("X-Goog-Expires", expires.to_owned()),
        ("X-Goog-SignedHeaders", names.clone()),
    ]);
    let query = params
        .iter()
        .map(|(n, v)| format!("{}={}", encode(n), encode(v)))
        .collect::<Vec<_>>()
        .join("&");
    let mut headers = String::new();
    for (n, v) in signed_headers {
        writeln!(headers, "{n}:{v}").unwrap();
    }
    let canonical = format!("{method}\n{path}\n{query}\n{headers}\n{names}\nUNSIGNED-PAYLOAD");
    let to_sign = format!(
        "GOOG4-RSA-SHA256\n{date}\n{scope}\n{}",
        hex(&Sha256::digest(canonical.as_bytes()))
    );
    let signature = SigningKey::<Sha256>::new(private_key.clone()).sign(to_sign.as_bytes());
    Url {
        path,
        query: format!("{query}&X-Goog-Signature={}", hex(&signature.to_bytes())),
    }
}

fn put(url: &Url, headers: &[(&str, &str)], body: &[u8]) -> StorageRequest {
    request("PUT", url, headers, body)
}

fn request(method: &str, url: &Url, headers: &[(&str, &str)], body: &[u8]) -> StorageRequest {
    StorageRequest {
        method: method.to_owned(),
        path: url.path.clone(),
        query: url.query.clone(),
        host: Some(HOST.to_owned()),
        headers: headers
            .iter()
            .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
            .collect(),
        app_check: Vec::new(),
        body: body.to_vec(),
        remote_peer: false,
    }
}

fn text(r: &StorageResponse) -> String {
    String::from_utf8_lossy(&r.body).into_owned()
}

fn exists(s: &StorageState, object: &str) -> bool {
    s.store
        .lock()
        .unwrap()
        .get(
            &BucketName::try_new(BUCKET).unwrap(),
            &ObjectName::try_new(object).unwrap(),
        )
        .is_some()
}

const DATE: &str = "20260829T120000Z";
const SIGNED: [(&str, &str); 3] = [
    ("content-type", "image/png"),
    ("host", HOST),
    ("x-goog-content-length-range", "0,10"),
];
const SENT: [(&str, &str); 2] = [
    ("content-type", "image/png"),
    ("x-goog-content-length-range", "0,10"),
];

fn signed_put(object: &str) -> Url {
    sign(key(), EMAIL, "PUT", object, DATE, "3600", &SIGNED)
}

#[test]
fn a_correctly_signed_upload_is_stored() {
    let s = strict_with_key();
    let r = handle(&s, put(&signed_put("up/a.png"), &SENT, b"png!"));
    assert_eq!(r.status, 200, "{}", text(&r));
    assert!(exists(&s, "up/a.png"));
}

#[test]
fn a_host_signed_without_its_port_is_accepted_as_the_admin_sdk_signs_it() {
    // `@google-cloud/storage` signs the host name alone for a local endpoint.
    let s = strict_with_key();
    let signed = [
        ("content-type", "image/png"),
        ("host", "127.0.0.1"),
        ("x-goog-content-length-range", "0,10"),
    ];
    let url = sign(key(), EMAIL, "PUT", "up/sdk.png", DATE, "3600", &signed);
    let r = handle(&s, put(&url, &SENT, b"png!"));
    assert_eq!(r.status, 200, "{}", text(&r));
    // Another host name is still a mismatch.
    let other = [
        ("content-type", "image/png"),
        ("host", "localhost"),
        ("x-goog-content-length-range", "0,10"),
    ];
    let url = sign(key(), EMAIL, "PUT", "up/other.png", DATE, "3600", &other);
    assert_eq!(handle(&s, put(&url, &SENT, b"png!")).status, 403);
}

#[test]
fn an_object_name_with_reserved_characters_verifies() {
    let s = strict_with_key();
    let name = "signed put/a # image (1).png";
    let r = handle(&s, put(&signed_put(name), &SENT, b"png!"));
    assert_eq!(r.status, 200, "{}", text(&r));
    assert!(exists(&s, name));
}

#[test]
fn each_recorded_cause_of_a_mismatch_is_a_403_signature_does_not_match() {
    let url = signed_put("up/a.png");
    let mut tampered = url.query.clone();
    let last = tampered.pop().unwrap();
    tampered.push(if last == '0' { '1' } else { '0' });
    let cases: Vec<(&str, StorageRequest)> = vec![
        (
            "tampered signature",
            put(
                &Url {
                    path: url.path.clone(),
                    query: tampered,
                },
                &SENT,
                b"png!",
            ),
        ),
        (
            "another content type",
            put(
                &url,
                &[
                    ("content-type", "text/plain"),
                    ("x-goog-content-length-range", "0,10"),
                ],
                b"png!",
            ),
        ),
        (
            "another range header",
            put(
                &url,
                &[
                    ("content-type", "image/png"),
                    ("x-goog-content-length-range", "0,3"),
                ],
                b"png!",
            ),
        ),
        (
            "another object",
            put(
                &Url {
                    path: format!("/{BUCKET}/up/other.png"),
                    query: url.query.clone(),
                },
                &SENT,
                b"png!",
            ),
        ),
        ("another method", request("GET", &url, &SENT, b"")),
    ];
    for (label, request) in cases {
        let s = strict_with_key();
        let r = handle(&s, request);
        assert_eq!(r.status, 403, "{label}: {}", text(&r));
        let body = text(&r);
        // The recorded production shape, byte for byte up to the two calculated texts.
        assert!(
            body.starts_with("<?xml version='1.0' encoding='UTF-8'?><Error><Code>SignatureDoesNotMatch</Code><Message>Access denied.</Message><Details>The request signature we calculated does not match the signature you provided. Check your Google secret key and signing method.</Details><StringToSign>GOOG4-RSA-SHA256\n20260829T120000Z\n20260829/auto/storage/goog4_request\n"),
            "{label}: {body}"
        );
        assert!(
            body.contains("</StringToSign><CanonicalRequest>"),
            "{label}: {body}"
        );
        assert!(
            body.ends_with("\nUNSIGNED-PAYLOAD</CanonicalRequest></Error>"),
            "{label}: {body}"
        );
        assert!(
            body.contains(
                "X-Goog-SignedHeaders=content-type%3Bhost%3Bx-goog-content-length-range\n"
            ),
            "{label}"
        );
        assert!(
            r.headers
                .iter()
                .any(|(k, v)| k.eq_ignore_ascii_case("content-type")
                    && v == "application/xml; charset=UTF-8"),
            "{label}"
        );
        assert!(
            !exists(&s, "up/a.png") && !exists(&s, "up/other.png"),
            "{label}"
        );
    }
}

#[test]
fn the_mismatch_body_shows_the_canonical_request_the_server_calculated() {
    let s = strict_with_key();
    let url = signed_put("up/a.png");
    let r = handle(
        &s,
        put(
            &url,
            &[
                ("content-type", "text/plain"),
                ("x-goog-content-length-range", "0,10"),
            ],
            b"x",
        ),
    );
    let body = text(&r);
    assert!(
        body.contains("<CanonicalRequest>PUT\n/demo-app.appspot.com/up/a.png\nX-Goog-Algorithm=GOOG4-RSA-SHA256&amp;X-Goog-Credential=signer%40demo-app.iam.gserviceaccount.com%2F20260829%2Fauto%2Fstorage%2Fgoog4_request&amp;X-Goog-Date=20260829T120000Z&amp;X-Goog-Expires=3600&amp;X-Goog-SignedHeaders=content-type%3Bhost%3Bx-goog-content-length-range\ncontent-type:text/plain\nhost:127.0.0.1:9199\nx-goog-content-length-range:0,10\n\ncontent-type;host;x-goog-content-length-range\nUNSIGNED-PAYLOAD</CanonicalRequest>"),
        "{body}"
    );
}

#[test]
fn without_a_registered_key_every_signature_is_accepted_as_before() {
    let url = signed_put("up/a.png");
    let mut tampered = url.query.clone();
    tampered.pop();
    tampered.push('0');
    for keys in [None, Some(&[][..])] {
        let s = state(TokenAcceptance::Verified, keys);
        let r = handle(
            &s,
            put(
                &Url {
                    path: url.path.clone(),
                    query: tampered.clone(),
                },
                &SENT,
                b"png!",
            ),
        );
        assert_eq!(r.status, 200, "{}", text(&r));
    }
}

#[test]
fn the_emulator_profile_ignores_the_keys() {
    let s = state(TokenAcceptance::EmulatorMock, Some(&[&public_pem()]));
    let url = signed_put("up/a.png");
    let mut tampered = url.query.clone();
    tampered.pop();
    tampered.push('0');
    let r = handle(
        &s,
        put(
            &Url {
                path: url.path,
                query: tampered,
            },
            &SENT,
            b"png!",
        ),
    );
    assert_eq!(r.status, 200, "{}", text(&r));
}

#[test]
fn a_signed_read_is_verified_too() {
    let s = strict_with_key();
    s.store
        .lock()
        .unwrap()
        .put(
            &BucketName::try_new(BUCKET).unwrap(),
            &ObjectName::try_new("r.txt").unwrap(),
            b"hello".to_vec(),
            NewMetadata::default(),
            Precondition::default(),
            START,
        )
        .unwrap();
    let host_only = [("host", HOST)];
    let url = sign(key(), EMAIL, "GET", "r.txt", DATE, "3600", &host_only);
    let ok = handle(&s, request("GET", &url, &[], b""));
    assert_eq!(ok.status, 200, "{}", text(&ok));
    assert_eq!(&ok.body[..], b"hello");
    let other = Url {
        path: format!("/{BUCKET}/r2.txt"),
        query: url.query.clone(),
    };
    let refused = handle(&s, request("GET", &other, &[], b""));
    assert_eq!(refused.status, 403);
    assert!(text(&refused).contains("<Code>SignatureDoesNotMatch</Code>"));
}

#[test]
fn a_signature_made_with_another_key_is_refused() {
    let s = strict_with_key();
    let url = sign(other_key(), EMAIL, "PUT", "up/a.png", DATE, "3600", &SIGNED);
    let r = handle(&s, put(&url, &SENT, b"png!"));
    assert_eq!(r.status, 403, "{}", text(&r));
}

#[test]
fn a_service_account_file_ties_its_key_to_its_client_email() {
    let account = serde_json::json!({
        "client_email": EMAIL,
        "private_key": key().to_pkcs8_pem(LineEnding::LF).unwrap().to_string(),
    })
    .to_string();
    let s = state(TokenAcceptance::Verified, Some(&[&account]));
    let ok = signed_put("up/a.png");
    assert_eq!(handle(&s, put(&ok, &SENT, b"png!")).status, 200);
    let stranger = sign(
        key(),
        "other@demo-app.iam.gserviceaccount.com",
        "PUT",
        "up/b.png",
        DATE,
        "3600",
        &SIGNED,
    );
    assert_eq!(handle(&s, put(&stranger, &SENT, b"png!")).status, 403);
}

#[test]
fn expiry_and_missing_signed_headers_keep_their_own_answers() {
    let s = strict_with_key();
    // An expired URL is an ExpiredToken whatever its signature is worth.
    let expired = sign(
        key(),
        EMAIL,
        "PUT",
        "up/a.png",
        "20260829T100000Z",
        "60",
        &SIGNED,
    );
    let r = handle(&s, put(&expired, &SENT, b"png!"));
    assert_eq!(r.status, 400, "{}", text(&r));
    assert!(text(&r).contains("<Code>ExpiredToken</Code>"));
    // A signed header the request lacks is the malformed-header answer, not a signature one.
    let r = handle(
        &s,
        put(
            &signed_put("up/a.png"),
            &[("x-goog-content-length-range", "0,10")],
            b"png!",
        ),
    );
    assert_eq!(r.status, 400, "{}", text(&r));
    assert!(text(&r).contains("<Code>MalformedSecurityHeader</Code>"));
}

#[test]
fn an_unsigned_or_signature_less_request_is_judged_as_before() {
    let s = strict_with_key();
    let url = Url {
        path: format!("/{BUCKET}/up/a.png"),
        query: "X-Goog-Algorithm=GOOG4-RSA-SHA256&X-Goog-Credential=signer%40demo-app.iam.gserviceaccount.com%2F20260829%2Fauto%2Fstorage%2Fgoog4_request&X-Goog-Date=20260829T120000Z&X-Goog-Expires=3600&X-Goog-SignedHeaders=host".to_owned(),
    };
    let r = handle(&s, put(&url, &SENT, b"png!"));
    assert_eq!(r.status, 400, "{}", text(&r));
    assert!(text(&r).contains("MissingSecurityHeader"));
}

mod round_trip {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(16))]

        /// A signature over any object name and any content type verifies, and the same URL
        /// with a different content type, object name or method is refused: the answer is the
        /// verification, never the shape of the name.
        #[test]
        fn any_signed_upload_is_stored_and_any_change_is_refused(
            name in "[a-zA-Z0-9 _.~#?&=+%()/-]{1,20}",
            content_type in "[a-z]{1,6}/[a-z]{1,6}",
        ) {
            prop_assume!(!name.starts_with('/') && !name.ends_with('/') && !name.contains("//") && !name.split('/').any(|part| part == "." || part == ".."));
            let signed = [
                ("content-type", content_type.as_str()),
                ("host", HOST),
                ("x-goog-content-length-range", "0,10"),
            ];
            let sent = [
                ("content-type", content_type.as_str()),
                ("x-goog-content-length-range", "0,10"),
            ];
            let url = sign(key(), EMAIL, "PUT", &name, DATE, "3600", &signed);
            let s = strict_with_key();
            let r = handle(&s, put(&url, &sent, b"png!"));
            prop_assert_eq!(r.status, 200, "{}", text(&r));
            let changed = format!("{content_type}x");
            let wrong_type = [
                ("content-type", changed.as_str()),
                ("x-goog-content-length-range", "0,10"),
            ];
            let s = strict_with_key();
            prop_assert_eq!(handle(&s, put(&url, &wrong_type, b"png!")).status, 403);
            let other = Url { path: format!("{}x", url.path), query: url.query.clone() };
            prop_assert_eq!(handle(&s, put(&other, &sent, b"png!")).status, 403);
        }
    }
}
